<script setup>
import{computed,onMounted,reactive,ref}from'vue';import{selfEvaluationApi as api}from'../../selfEvaluationApi'
const tasks=ref([]),versions=ref([]),orgs=ref([]),selected=ref(null),formData=ref(null),message=ref(''),msgType=ref('info'),showCreate=ref(false),loading=ref(false)
const form=reactive({taskCode:'',taskName:'',evaluationYear:new Date().getFullYear(),taskType:'ANNUAL',startDate:'',endDate:'',description:'',indicatorVersionId:'',orgUnitIds:[]})
const isManager=computed(()=>!formData.value||['NOT_STARTED','DRAFT','RETURNED'].includes(formData.value.status))
function msg(text,type='info'){message.value=text;msgType.value=type;if(type!=='error')setTimeout(()=>{if(message.value===text){message.value='';msgType.value='info'}},4000)}
async function load(){loading.value=true;try{[tasks.value,versions.value,orgs.value]=await Promise.all([api.tasks(),api.versions(),api.orgs()])}catch(e){msg(e.message||'后端连接失败，请确认后端已启动','error')}finally{loading.value=false}}
async function create(){try{if(!form.indicatorVersionId){msg('请选择已发布的指标版本','error');return}if(!form.orgUnitIds.length){msg('请至少选择一个参评机构','error');return}if(!form.taskCode||!form.taskName){msg('请填写任务编码和名称','error');return}if(!form.startDate||!form.endDate){msg('请选择起止日期','error');return}await api.createTask({...form});showCreate.value=false;msg('自评任务草稿已创建','success');await load()}catch(e){msg(e.message||'创建失败','error')}}
async function open(x){try{loading.value=true;selected.value=await api.task(x.id);formData.value=null}catch(e){msg(e.message,'error')}finally{loading.value=false}}
async function publish(x){try{await api.publish(x.id);msg('任务已发布并冻结三级指标快照','success');await load();await open(x)}catch(e){msg(e.message,'error')}}
async function cancelTask(x){const opinion=prompt('取消原因');if(!opinion)return;try{await api.cancel(x.id,{action:'CANCEL',opinion});msg('任务已取消','success');await load()}catch(e){msg(e.message,'error')}}
async function openForm(x){try{loading.value=true;formData.value=await api.form(x.id)}catch(e){msg(e.message,'error')}finally{loading.value=false}}
async function saveEntry(x){const editable=isManager.value;if(!editable)return;if(x.self_score==null||x.self_score===''){msg('请填写自评分','error');return}if(!x.performance_description||x.performance_description.length<5){msg('履职说明至少5个字','error');return}try{await api.saveEntry(x.id,{selfScore:Number(x.self_score),performanceDescription:x.performance_description,completionStatus:x.completion_status||'',rowVersion:x.row_version});msg('自评指标已暂存','success');formData.value=await api.form(formData.value.id)}catch(e){msg(e.message,'error')}}
async function submit(){let canSubmit=formData.value.entries.every(e=>e.self_score!=null&&e.performance_description&&e.performance_description.length>=5);if(!canSubmit){msg('所有指标必须填写自评分和履职说明（至少5字）','error');return}try{formData.value=await api.submit(formData.value.id,{opinion:'提交部门自评'});msg('自评已提交，等待复核','success');if(selected.value)selected.value=await api.task(selected.value.id)}catch(e){msg(e.message,'error')}}
async function review(action){const opinion=prompt(action==='CONFIRM'?'确认意见':'退回意见');if(!opinion)return;try{formData.value=await api.review(formData.value.id,{action,opinion});msg(action==='CONFIRM'?'自评已完成':'自评已退回修改','success');if(selected.value)selected.value=await api.task(selected.value.id)}catch(e){msg(e.message,'error')}}
onMounted(load)
</script>
<template><section class="page active"><div class="alert alert-info">部门自评使用已发布三级指标快照；规则检查代替AI初审，提交后只读，退回后可修改重提。<span v-if="loading" style="margin-left:8px">⏳ 加载中...</span></div><div v-if="message" class="alert" :class="msgType==='error'?'alert-danger':msgType==='success'?'alert-success':'alert-warning'">{{message}}</div>
<div class="card"><div class="card-header"><h3>📋 自评任务看板</h3><div class="btn-group"><button class="btn btn-primary" @click="showCreate=true" :disabled="!versions.length">创建任务</button><button class="btn btn-outline" @click="load">刷新</button></div></div><table><thead><tr><th>任务</th><th>年度</th><th>类型</th><th>指标版本</th><th>机构</th><th>进度</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-if="loading&&!tasks.length"><td colspan="8" class="empty-cell">正在加载任务列表...</td></tr><tr v-else-if="!tasks.length"><td colspan="8" class="empty-cell"><span v-if="!versions.length">请先在"指标体系初始化配置"(m1-7)中创建指标体系并在"指标动态管理功能"(m1-8)中发布一个版本。</span><span v-else>点击"创建任务"开始。</span></td></tr><tr v-for="x in tasks" :key="x.id"><td>{{x.task_name}}</td><td>{{x.evaluation_year}}</td><td><span class="tag tag-info">{{x.task_type==='ANNUAL'?'年度':'专项'}}</span></td><td>{{x.version_name}}</td><td>{{x.org_count}}</td><td><div class="progress-bar" style="width:80px;display:inline-block;vertical-align:middle"><div class="fill" :class="x.progress>=100?'fill-blue':x.progress>=50?'fill-yellow':''" :style="{width:x.progress+'%'}"></div></div> {{x.progress}}%</td><td><span class="tag" :class="x.status==='PUBLISHED'||x.status==='FILLING'?'tag-success':x.status==='DRAFT'?'tag-warning':x.status==='CANCELLED'?'tag-danger':'tag-info'">{{x.status}}</span></td><td><button class="btn btn-sm btn-outline" @click="open(x)">详情</button> <button v-if="x.status==='DRAFT'" class="btn btn-sm btn-primary" @click="publish(x)">发布</button> <button v-if="['DRAFT','PUBLISHED','FILLING','SUBMITTED','RETURNED'].includes(x.status)" class="btn btn-sm btn-outline" @click="cancelTask(x)">取消</button></td></tr></tbody></table></div>
<div v-if="selected" class="card"><div class="card-header"><h3>{{selected.task_name}} · 机构进度</h3><span class="extra">{{selected.status}} / {{selected.evaluation_year}}年</span></div><table><thead><tr><th>机构</th><th>完成指标</th><th>总分</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="x in selected.organizations" :key="x.id"><td>{{x.unit_name}}</td><td>{{x.completed_items}}/{{x.total_items}}</td><td>{{x.total_score||0}}</td><td><span class="tag" :class="x.status==='COMPLETED'?'tag-success':x.status==='SUBMITTED'?'tag-info':x.status==='RETURNED'?'tag-warning':x.status==='NOT_STARTED'?'tag-default':'tag-info'">{{x.status}}</span></td><td><button class="btn btn-sm btn-primary" :disabled="selected.status==='DRAFT'" @click="openForm(x)">{{['SUBMITTED','COMPLETED'].includes(x.status)?'复核查看':'填报'}}</button></td></tr></tbody></table></div>
<div v-if="formData" class="card"><div class="card-header"><h3>{{formData.unit_name}} · 自评填报</h3><span class="tag" :class="formData.status==='SUBMITTED'?'tag-info':formData.status==='COMPLETED'?'tag-success':formData.status==='RETURNED'?'tag-warning':'tag-info'">{{formData.status}}</span></div><div class="alert" :class="isManager?'alert-info':'alert-warning'">{{isManager?'可编辑状态：填写自评分和履职说明后，点暂存保存，指标数据提交后只读。':'当前状态只读，退回修改后才可编辑。'}}</div><table><thead><tr><th>指标</th><th>标准分</th><th>自评分</th><th>完成情况</th><th>履职说明</th><th>操作</th></tr></thead><tbody><tr v-for="x in formData.entries" :key="x.id"><td><strong>{{x.indicator_code}}</strong> {{x.indicator_name}}</td><td>{{x.standard_score}}</td><td><input v-model.number="x.self_score" type="number" min="0" :max="x.standard_score" step="0.1" :disabled="!isManager" style="width:72px"></td><td><input v-model="x.completion_status" :disabled="!isManager" style="width:100px" placeholder="完成/部分完成/未完成"></td><td><textarea v-model="x.performance_description" :disabled="!isManager" rows="2" style="width:200px" placeholder="请描述履职情况（至少5字）"></textarea></td><td><button v-if="isManager" class="btn btn-sm btn-outline" @click="saveEntry(x)">暂存</button><span v-else class="tag tag-default">已提交</span></td></tr></tbody></table><div class="btn-group" style="margin-top:12px"><button v-if="['DRAFT','RETURNED'].includes(formData.status)" class="btn btn-primary" @click="submit">提交复核</button><button v-if="formData.status==='SUBMITTED'" class="btn btn-primary" @click="review('CONFIRM')">确认完成</button><button v-if="formData.status==='SUBMITTED'" class="btn btn-outline" @click="review('RETURN')">退回修改</button></div></div>
<div v-if="showCreate" class="modal-overlay" @click.self="showCreate=false"><div class="modal"><h3>创建自评任务</h3><div class="form-grid"><div class="form-item"><label>任务编码 *</label><input v-model="form.taskCode" placeholder="如 SELF-2026-01"></div><div class="form-item"><label>任务名称 *</label><input v-model="form.taskName" placeholder="如 2026年度自评"></div><div class="form-item"><label>年度</label><input v-model.number="form.evaluationYear" type="number"></div><div class="form-item"><label>类型</label><select v-model="form.taskType"><option value="ANNUAL">年度自评</option><option value="SPECIAL">专项自评</option></select></div><div class="form-item"><label>开始日期 *</label><input v-model="form.startDate" type="date"></div><div class="form-item"><label>结束日期 *</label><input v-model="form.endDate" type="date"></div><div class="form-item full"><label>已发布指标版本 *</label><select v-model="form.indicatorVersionId"><option value="">请选择已发布版本</option><option v-for="x in versions" :key="x.id" :value="x.id">{{x.system_name}} / {{x.version_name}}（{{x.item_count}}项三级指标）</option></select><div v-if="!versions.length" class="hint">暂无已发布指标版本，请先在指标体系管理中创建并发布版本。</div></div><div class="form-item full"><label>参评机构 *（可多选）</label><div class="choice-list"><label v-for="x in orgs" :key="x.id" class="choice-label"><input v-model="form.orgUnitIds" type="checkbox" :value="x.id"> {{x.unit_name}}（{{x.unit_code}}）</label></div></div><div class="form-item full"><label>说明</label><textarea v-model="form.description" rows="2" placeholder="任务说明（选填）"></textarea></div></div><div class="btn-group" style="margin-top:12px"><button class="btn btn-primary" @click="create">保存草稿</button> <button class="btn btn-outline" @click="showCreate=false">取消</button></div></div></div>
</section></template>
<style scoped>.modal-overlay{position:fixed;inset:0;background:#0006;z-index:1000;display:flex;align-items:center;justify-content:center}.modal{background:#fff;padding:22px;border-radius:12px;width:min(800px,94vw);max-height:88vh;overflow:auto}.form-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}.full{grid-column:1/-1}.choice-list{display:grid;grid-template-columns:repeat(2,1fr);max-height:200px;overflow:auto;border:1px solid #ddd;border-radius:6px;padding:8px}.choice-label{margin:4px 0;display:flex;align-items:center;gap:4px;cursor:pointer;font-size:14px}.choice-label:hover{background:#f0f4ff}.hint{color:#e67e22;font-size:13px;margin-top:4px}.empty-cell{text-align:center;color:#999;padding:24px!important}.progress-bar{height:6px;background:#eee;border-radius:3px;overflow:hidden}.fill{height:100%;background:#ddd;transition:width .3s}.fill-blue{background:#2b7bdb}.fill-yellow{background:#e67e22}.btn-group{display:flex;gap:8px;flex-wrap:wrap}@media(max-width:700px){.form-grid{grid-template-columns:1fr}.full{grid-column:auto}}</style>
